import styles from "./resulting-media-modal.module.less";
import { UseQueryResult } from "@tanstack/react-query";
import { Modal } from "@/core/components/primitives/modal/modal";
import { OutlineButton, SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { SingleMediaResponse } from "@parksandresorts/webapiproxy-types";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { getTitleFromRideId } from "../../../helpers";

type Props = {
  isOpen: boolean;
  imageNumberSearchString: string;
  searchQueryResult: UseQueryResult<SingleMediaResponse, Error>;
  closeModal: () => void;
  consent: () => void;
};
export const ResultingMediaModal = ({
  isOpen,
  imageNumberSearchString,
  searchQueryResult,
  closeModal,
  consent,
}: Props) => {
  const { t } = useTranslation();
  const wrapperElement = useContentContainerRef();

  const rideTitle = getTitleFromRideId(searchQueryResult.data?.item?.attractionId);

  return (
    <Modal
      isOpen={isOpen}
      onClose={closeModal}
      innerClassName={styles.modalInner}
      refWrapperElement={wrapperElement ?? undefined}
    >
      {searchQueryResult.data?.item && !searchQueryResult.isLoading && (
        <div className={styles.modalContent} data-testid="digital-ride-media-resulting-media-modal-content">
          <h3>{t("rideMediaResultingMediaModalHeading")}</h3>
          <h6>
            {rideTitle ? `${rideTitle} •` : ""} {imageNumberSearchString}
          </h6>
          {searchQueryResult.data.item.mediaType === "Photo" && (
            <img
              src={searchQueryResult.data.item.url!}
              alt={rideTitle}
              data-testid="digital-ride-media-resulting-media-modal-photo"
            />
          )}
          {searchQueryResult.data.item.mediaType === "Video" && (
            <video
              src={searchQueryResult.data.item.url!}
              controls
              data-testid="digital-ride-media-resulting-media-modal-video"
            />
          )}
          <p className="body-xxs">{t("rideMediaResultingMediaModalConsentParagraph")}</p>
          <div className={styles.buttonWrapper}>
            <OutlineButton label={t("no")} isFullWidth onClick={closeModal} />
            <SecondaryButton
              label={t("yes")}
              isFullWidth
              onClick={consent}
              testId="digital-ride-media-resulting-media-modal-confirm-button"
            />
          </div>
        </div>
      )}
    </Modal>
  );
};
