import styles from "./flippable-item.module.less";

type Props = {
  children: [React.ReactNode, React.ReactNode]; //Typesafe way of saying "exactly two children"
  isFlipped: boolean;
  className?: string;
};

export const FlippableItem = ({ children, isFlipped, className }: Props) => {
  return (
    <div className={`${styles.flipCard} ${className ?? ""}`}>
      <div className={`${styles.flipCardInner} ${isFlipped ? styles.flipped : ""}`}>
        <div className={styles.flipCardFront}>{children[0]}</div>
        <div className={styles.flipCardBack}>{children[1]}</div>
      </div>
    </div>
  );
};
