import Card from "@/core/components/primitives/card/card";
import SelectBox from "@/core/components/primitives/select-box/select-box";
import InputField from "@/core/components/primitives/input-field/input-field";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import InputError from "@/core/components/primitives/input-error/input-error";
import { SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { AnimatePresence } from "framer-motion";
import styles from "./search-card.module.less";
import { UseQueryResult } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { SingleMediaResponse } from "@parksandresorts/webapiproxy-types";
import { BackButton } from "../../../elements/back-button/back-button";
import { useMemo, useRef, useState } from "react";
import Banner from "@/core/components/primitives/banner/banner";
import { DateHelper, TodayHelper } from "@/core/helpers";

type Props = {
  isVisible: boolean;
  rides: Array<{
    pomvomCode: string;
    rideName: string;
  }>;
  queryResult: UseQueryResult<SingleMediaResponse, Error>;
  formState: {
    rideId: string | undefined;
    imageNumberPrefix: string | undefined;
    imageNumber: string | undefined;
    visitDate: string;
  };
  onChangeRideInput: (rideId: string) => void;
  onChangeVisitDate: (visitDate: string) => void;
  onChangeImageNumberPrefixInput: (imageNumberPrefix: string) => void;
  onChangeImageNumberInput: (imageNumber: string) => void;
  onClickSearch: (rideId: string, visitDate: string, imageNumberPrefix: string, imageNumber: string) => void;
  navigateToStartPage: () => void;
};

export const SearchCard = ({
  isVisible,
  rides,
  queryResult,
  formState,
  onChangeRideInput,
  onChangeVisitDate,
  onChangeImageNumberPrefixInput,
  onChangeImageNumberInput,
  onClickSearch,
  navigateToStartPage,
}: Props) => {
  const rideSelectBoxOptions = rides.map((ride) => ({
    value: ride.pomvomCode,
    label: ride.rideName,
  }));

  const mediaNumberInputRef = useRef<HTMLInputElement>(null);
  const [hasAttemptedSearch, setHasAttemptedSearch] = useState(false);

  const { t } = useTranslation();

  // Pomvom allows for searching for media 45 days back. Searching in the future does not make sense.
  const { minDate, maxDate } = useMemo(() => {
    const now = TodayHelper.getNow();
    return {
      minDate: DateHelper.toStringYYYYMMDD(DateHelper.addDays(now, -45)),
      maxDate: DateHelper.toStringYYYYMMDD(now),
    };
  }, []);

  const isRideInvalid = hasAttemptedSearch && !formState.rideId;
  const isImageNumberPrefixInvalid = hasAttemptedSearch && !formState.imageNumberPrefix;
  const isImageNumberInvalid = hasAttemptedSearch && !formState.imageNumber;

  return (
    <AnimatePresence>
      {isVisible && (
        <Card
          className={styles.card}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          initial={{ opacity: 0 }}
          transition={{ duration: 0.2 }}
        >
          <BackButton onClick={navigateToStartPage} labelOverride={t("rideMediaSearchCardBackButtonLabel")} />
          <h3>{t("rideMediaSearchCardHeading")}</h3>

          {queryResult.isError && (
            <Banner
              border
              type="warning"
              heading={t("rideMediaSearchCardErrorHeading")}
              data-testid="digital-ride-media-search-card-error-banner"
            >
              <p>{t("rideMediaSearchCardErrorParagraph1")}</p>
              <p>{t("rideMediaSearchCardErrorParagraph2")}</p>
            </Banner>
          )}

          <SelectBox
            description={t("rideMediaSearchCardSelectRideDescription")}
            options={rideSelectBoxOptions}
            notSelectedText={t("rideMediaSearchCardSelectRideDescription")}
            value={formState.rideId}
            isRequired={true}
            data-testid="digital-ride-media-search-card-ride-select"
            onChange={(_, value) => {
              onChangeRideInput(value);
            }}
            errorText={t("rideMediaSearchCardSelectRideError")}
            isValid={!isRideInvalid}
          />

          <InputField
            label={t("rideMediaSearchCardDateDescription")}
            type="date"
            value={formState.visitDate}
            min={minDate}
            max={maxDate}
            onChange={(_, value) => onChangeVisitDate(value)}
          />

          <InputLabel label={t("rideMediaSearchCardMediaNumberInputLabel")} isRequired={true} />
          <div className={styles.prefixAndNumberWrapper}>
            <InputField
              inputMode="text"
              size={1}
              maxLength={1}
              placeholder="X"
              value={formState.imageNumberPrefix}
              isValid={!isImageNumberPrefixInvalid}
              isGroupedInput={true}
              onChange={(_, value) => {
                const previousNumCharactersEntered = formState.imageNumberPrefix?.length ?? 0;
                const numberOfCharactersEntered = value.length;
                const shouldFocusOnNextInput = previousNumCharactersEntered === 0 && numberOfCharactersEntered === 1;
                if (shouldFocusOnNextInput) {
                  mediaNumberInputRef.current?.focus();
                }
                onChangeImageNumberPrefixInput(value.toUpperCase());
              }}
              data-testid="digital-ride-media-search-card-image-prefix"
            />
            <p>-</p>
            <InputField
              inputRef={mediaNumberInputRef}
              inputMode="tel"
              placeholder={t("rideMediaSearchCardMediaNumberInputPlaceholder")}
              data-testid="digital-ride-media-search-card-image-number"
              value={formState.imageNumber}
              isValid={!isImageNumberInvalid}
              isGroupedInput={true}
              onChange={(_, value) => {
                onChangeImageNumberInput(value);
              }}
            />
          </div>
          <InputError
            showError={isImageNumberPrefixInvalid || isImageNumberInvalid}
            errorText={
              isImageNumberPrefixInvalid || isImageNumberInvalid
                ? t("rideMediaSearchCardMediaNumberInputError")
                : undefined
            }
            data-testid="digital-ride-media-search-card-image-number-error"
          />
          <SecondaryButton
            label={
              !queryResult.isLoading
                ? t("rideMediaSearchCardButtonTextDefault")
                : t("rideMediaSearchCardButtonTextLoading")
            }
            isFullWidth
            isDisabled={queryResult.isLoading}
            onClick={() => {
              setHasAttemptedSearch(true);
              const rideId = formState.rideId;
              const visitDate = formState.visitDate;
              const imageNumberPrefix = formState.imageNumberPrefix;
              const imageNumber = formState.imageNumber?.toString();
              onClickSearch(rideId || "", visitDate, imageNumberPrefix || "", imageNumber || "");
            }}
            iconLeftNew={queryResult.isLoading ? "loading" : undefined}
            testId="digital-ride-media-search-album-form-search-button"
          />
        </Card>
      )}
    </AnimatePresence>
  );
};
