import { DateHelper, DateString, TodayHelper, multipleClassNames } from "@/core/helpers";
import styles from "./digital-ride-media-search-block.module.less";
import structure from "@/core/styling/structure.module.less";
import { FlippableItem } from "@/core/components/primitives/flippable-item/flippable-item";
import { IDigitalRideMediaService } from "@/core/services";
import { useEffect, useMemo, useState } from "react";
import { ResultingMediaModal, SearchCard } from "./elements";
import { SaveToAlbum } from "../elements";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { z } from "zod";
import { useHashState } from "@/core/hooks";

const formStateSchema = z.object({
  rideId: z.union([z.string(), z.number()]).optional(),
  imageNumberPrefix: z.union([z.string(), z.number()]).optional(),
  imageNumber: z.union([z.string(), z.number()]).optional(),
  visitDate: z.string().date().optional(),
});

type Props = {
  rides: Array<{
    pomvomCode: string;
    rideName: string;
  }>;
  service: IDigitalRideMediaService;
  pomvomCodeToRideIdConverterConfig: Array<{ rideId: number; pomvomCode: string }>;
  navigateToAlbum: (albumId: string, newlyCreated: boolean, mediaIdAdded: string) => void;
  navigateToStartPage: () => void;
};

const DigitalRideMediaSearchBlock = ({
  rides,
  service,
  pomvomCodeToRideIdConverterConfig,
  navigateToAlbum,
  navigateToStartPage,
}: Props) => {
  const queryClient = useQueryClient();
  const [displaySaveToAlbum, setDisplaySaveToAlbum] = useState<boolean>(false);

  const today = useMemo(() => DateHelper.toStringYYYYMMDD(TodayHelper.getNow()), []);

  const [{ rideIdToSearch, imageNumberPrefixToSearch, imageNumberToSearch, visitDateToSearch }, setSearchParameters] =
    useState({
      rideIdToSearch: "",
      imageNumberPrefixToSearch: "",
      imageNumberToSearch: "",
      visitDateToSearch: today,
    });

  const [hasInteractedWithForm, setHasInteractedWithForm] = useState<boolean>(false);

  const [formState, setFormState] = useHashState(formStateSchema);

  const formStateAsString = {
    rideId: formState.rideId?.toString(),
    imageNumberPrefix: formState.imageNumberPrefix?.toString(),
    imageNumber: formState.imageNumber?.toString(),
    visitDate: formState.visitDate ?? today,
  };

  /**
   * This is responsible for automatically searching when "deeplinking" a search with the hash parameters.
   */
  useEffect(() => {
    const hasValuesInHashState = formState.rideId && formState.imageNumberPrefix && formState.imageNumber;
    const hasNotPerformedSearch = !rideIdToSearch && !imageNumberPrefixToSearch && !imageNumberToSearch;
    if (hasValuesInHashState && hasNotPerformedSearch && !hasInteractedWithForm) {
      const rideIdFromPomvomCode = pomvomCodeToRideIdConverterConfig.find(
        //These non-null assertions are safe because of the check above
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        (config) => config.pomvomCode === formState.rideId!.toString(),
      )?.rideId;
      if (!rideIdFromPomvomCode) {
        console.warn("No rideId found for the given pomvom code: ", formState.rideId);
        return;
      }
      setSearchParameters({
        rideIdToSearch: rideIdFromPomvomCode.toString(),
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        imageNumberPrefixToSearch: formState.imageNumberPrefix!.toString(),
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        imageNumberToSearch: formState.imageNumber!.toString(),
        visitDateToSearch: (formState.visitDate as DateString | undefined) ?? today,
      });
    }
  }, [
    today,
    formState,
    rideIdToSearch,
    imageNumberPrefixToSearch,
    imageNumberToSearch,
    hasInteractedWithForm,
    pomvomCodeToRideIdConverterConfig,
  ]);

  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  const searchQueryResult = useQuery({
    queryKey: ["search-ride-media", rideIdToSearch, imageNumberPrefixToSearch, imageNumberToSearch, visitDateToSearch],
    enabled: !!rideIdToSearch && !!imageNumberPrefixToSearch && !!imageNumberToSearch,
    queryFn: () =>
      service.searchForMedia(rideIdToSearch, imageNumberPrefixToSearch, imageNumberToSearch, visitDateToSearch),
  });

  const {
    mutate: createNewAlbum,
    isPending: isLoadingCreateAlbum,
    error: createNewAlbumError,
  } = useMutation({
    mutationFn: (mediaId: string) => service.createNewAlbumWithInitialMedia([mediaId]),
    onSuccess: (data, mediaId) => {
      const updatedAlbumId = data.album.albumId;
      navigateToAlbum(updatedAlbumId, true, mediaId);
    },
  });

  const [isSavingToExistingAlbumId, setIsSavingToExistingAlbumId] = useState<string>();
  const [savingToExistingAlbumErrorAlbumId, setSavingToExistingAlbumErrorAlbumId] = useState<string>();
  const { mutate: saveToExistingAlbum } = useMutation({
    mutationKey: ["save-to-existing-album", searchQueryResult.data?.item?.mediaId],
    onMutate: (input) => {
      setIsSavingToExistingAlbumId(input.albumId);
    },
    mutationFn: (input: { mediaId: string; albumId: string }) => service.addMediaToAlbum(input.albumId, input.mediaId),
    onSuccess: (data, { mediaId }) => {
      const updatedAlbumId = data.album.albumId;
      queryClient.resetQueries({ queryKey: ["album-media", updatedAlbumId] });
      navigateToAlbum(updatedAlbumId, false, mediaId);
    },
    onError: (_error, data) => {
      setIsSavingToExistingAlbumId(undefined);
      setSavingToExistingAlbumErrorAlbumId(data.albumId);
    },
  });

  const handleCreateNewAlbum = async () => {
    const mediaId = searchQueryResult.data?.item?.mediaId;
    if (!mediaId) {
      console.error("No mediaId found in search result");
      return;
    }
    createNewAlbum(mediaId);
  };

  const [hasConsented, setHasConsented] = useState<boolean>(false);

  const resetSearch = () => {
    setSearchParameters({
      rideIdToSearch: "",
      imageNumberPrefixToSearch: "",
      imageNumberToSearch: "",
      visitDateToSearch: today,
    });
  };

  return (
    <section className={multipleClassNames(styles.outerWrapper, structure.block, structure.blockMaxWidthS)}>
      <div className={styles.innerWrapper}>
        <FlippableItem isFlipped={displaySaveToAlbum}>
          <SearchCard
            isVisible={!displaySaveToAlbum}
            rides={rides}
            queryResult={searchQueryResult}
            formState={formStateAsString}
            onChangeRideInput={(rideId) => {
              setHasInteractedWithForm(true);
              setFormState({ rideId: rideId });
            }}
            onChangeImageNumberPrefixInput={(imageNumberPrefix) => {
              setHasInteractedWithForm(true);
              setFormState({ imageNumberPrefix: imageNumberPrefix });
            }}
            onChangeImageNumberInput={(imageNumber) => {
              const isValidNumber = !isNaN(Number(imageNumber));
              setHasInteractedWithForm(true);
              if (isValidNumber) {
                setFormState({ imageNumber });
              }
              if (imageNumber === "") {
                setFormState({ imageNumber: undefined });
              }
            }}
            onChangeVisitDate={(visitDate) => {
              setHasInteractedWithForm(true);
              setFormState({ visitDate });
            }}
            onClickSearch={(pomvomCode, visitDate, imageNumberPrefix, imageNumber) => {
              const rideIdFromPomvomCode = pomvomCodeToRideIdConverterConfig.find(
                (config) => config.pomvomCode === pomvomCode,
              )?.rideId;
              if (!rideIdFromPomvomCode) {
                console.warn("No rideId found for the given pomvom code: ", pomvomCode);
                return;
              }

              setSearchParameters({
                rideIdToSearch: rideIdFromPomvomCode.toString(),
                imageNumberPrefixToSearch: imageNumberPrefix,
                imageNumberToSearch: imageNumber,
                visitDateToSearch: visitDate as DateString,
              });
              setHasConsented(false);
            }}
            navigateToStartPage={navigateToStartPage}
          />

          <SaveToAlbum
            wrappingElement="card"
            service={service}
            isVisible={displaySaveToAlbum}
            visitDate={visitDateToSearch}
            goBack={() => {
              setDisplaySaveToAlbum(false);
              window.scrollTo({ top: 0, behavior: "smooth" });
            }}
            createNewAlbum={handleCreateNewAlbum}
            createNewAlbumError={createNewAlbumError}
            addToExistingAlbum={(albumId) => {
              const mediaId = searchQueryResult.data?.item?.mediaId;
              if (mediaId) {
                saveToExistingAlbum({ mediaId, albumId });
              }
            }}
            isLoadingCreateAlbum={isLoadingCreateAlbum}
            isLoadingSaveToExistingAlbumId={isSavingToExistingAlbumId}
            isErrorOnSaveToExistingAlbumId={savingToExistingAlbumErrorAlbumId}
          />
        </FlippableItem>

        <ResultingMediaModal
          isOpen={!!searchQueryResult.data && !hasConsented}
          imageNumberSearchString={`${imageNumberPrefixToSearch}-${imageNumberToSearch}`}
          searchQueryResult={searchQueryResult}
          closeModal={() => {
            resetSearch();
            setHasInteractedWithForm(true);
          }}
          consent={() => {
            setHasConsented(true);
            setTimeout(() => {
              setDisplaySaveToAlbum(true);
              window.scrollTo({ top: 0, behavior: "smooth" });
            }, 300);
          }}
        />
      </div>
    </section>
  );
};

export default DigitalRideMediaSearchBlock;
